import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
def model(p,t,A):
    out=np.zeros_like(t)
    for i in range(4):
        c,a,b,k=p[4*i:4*i+4]
        out=out+ c*t**a*A**b*np.exp(-k*t)
    return out
best=[1e9,None]
rng=np.random.default_rng(1)
