    p0=[]
    for i in range(4):
        p0+= [rng.normal()*3, rng.uniform(-2,2), rng.uniform(-2,2), rng.uniform(-0.5,1)]
    try:
        r=least_squares(lambda p: model(p,t,A)-y, p0, max_nfev=500)
